// HasEntry applies the HasEdge predicate on the "entry" edge.
func HasEntry() predicate.ModelCatalogBinding {
	return predicate.ModelCatalogBinding(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, EntryColumn),
			sqlgraph.Edge(sqlgraph.M2O, false, EntryTable, EntryColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasEntryWith applies the HasEdge predicate on the "entry" edge with a given conditions (other predicates).
func HasEntryWith(preds ...predicate.ModelCatalogEntry) predicate.ModelCatalogBinding {
	return predicate.ModelCatalogBinding(func(s *sql.Selector) {
		step := newEntryStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

